export type DeckFilter = {
  type: 'all' | 'lesson' | 'category';
  id?: string;
  title: string;
};

export function getCategoryById(id: string): ThemedCategory | undefined {
  return THEMED_CATEGORIES.find(c => c.id === id);
}

export function getLessonByNumber(num: number): LessonBatch | undefined {
  return LESSON_BATCHES.find(l => l.number === num);
}

export function getLessonById(id: string): LessonBatch | undefined {
  return LESSON_BATCHES.find(l => l.id === id);
}

export function getBatchProgress(wordIds: number[], learnedSet: Set<number>) {
  let count = 0;
  for (const id of wordIds) {
    if (learnedSet.has(id)) count++;
  }
  const total = wordIds.length;
  const pct = total > 0 ? Math.round((count / total) * 100) : 0;
  return { learned: count, total, pct };
}

